from pathlib import Path

import pytest


def read_note(name: str) -> str:
    """Return the UTF-8 text of the file `name` inside the `notes` directory.

    `notes` is relative to the current working directory. `name` is untrusted
    and is interpreted relative to `notes`; it may name a file in a
    subdirectory of `notes` (e.g. "sub/a.txt").

    Returns "" if the file is missing, is not a regular file, cannot be read
    or decoded as UTF-8, or if `name` is invalid (empty, contains a NUL byte,
    too long, etc.).

    Returns "" whenever the fully resolved target (after resolving "..",
    absolute paths, and symlinks) would lie outside the `notes` directory.
    No form of `name` may cause a file outside `notes` to be read. Never
    raises for any `name`.
    """
    if not name or "\x00" in name or len(name) > 4096:
        return ""
    try:
        root = Path("notes").resolve()
        target = (root / name).resolve()
        if target == root or not target.is_relative_to(root):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    notes.mkdir()
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_note(sandbox: Path) -> None:
    (sandbox / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("a.txt") == "hello"


def test_reads_unicode_note(sandbox: Path) -> None:
    (sandbox / "notes" / "u.txt").write_text("héllo ✓", encoding="utf-8")
    assert read_note("u.txt") == "héllo ✓"


def test_reads_nested_note(sandbox: Path) -> None:
    sub = sandbox / "notes" / "sub"
    sub.mkdir()
    (sub / "b.txt").write_text("nested", encoding="utf-8")
    assert read_note("sub/b.txt") == "nested"


def test_dotdot_that_stays_inside_is_allowed(sandbox: Path) -> None:
    sub = sandbox / "notes" / "sub"
    sub.mkdir()
    (sandbox / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("sub/../a.txt") == "hello"


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert read_note("nope.txt") == ""


def test_missing_notes_directory_gives_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_note("a.txt") == ""


def test_empty_and_dot_names_give_empty(sandbox: Path) -> None:
    assert read_note("") == ""
    assert read_note(".") == ""
    assert read_note("..") == ""


def test_directory_name_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    assert read_note("sub") == ""


def test_parent_traversal_blocked(sandbox: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("../../secret.txt") == ""
    assert read_note("./../secret.txt") == ""


def test_traversal_via_subdirectory_blocked(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("nonexistent/../../secret.txt") == ""


def test_absolute_path_blocked(sandbox: Path) -> None:
    assert read_note(str(sandbox / "secret.txt")) == ""
    assert read_note(str((sandbox / "secret.txt").resolve())) == ""


def test_sibling_directory_with_common_prefix_blocked(sandbox: Path) -> None:
    evil = sandbox / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("evil", encoding="utf-8")
    assert read_note("../notes_evil/x.txt") == ""


def test_symlink_file_escaping_notes_blocked(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_note("link.txt") == ""


def test_symlink_dir_escaping_notes_blocked(sandbox: Path) -> None:
    link = sandbox / "notes" / "linkdir"
    try:
        link.symlink_to(sandbox, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_note("linkdir/secret.txt") == ""


def test_symlink_staying_inside_notes_allowed(sandbox: Path) -> None:
    real = sandbox / "notes" / "real.txt"
    real.write_text("real", encoding="utf-8")
    link = sandbox / "notes" / "alias.txt"
    try:
        link.symlink_to(real)
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_note("alias.txt") == "real"


def test_nul_byte_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("a.txt\x00../../secret.txt") == ""
    assert read_note("a\x00b") == ""


def test_overlong_name_gives_empty(sandbox: Path) -> None:
    assert read_note("a" * 10000) == ""


def test_undecodable_file_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "bin.dat").write_bytes(b"\xff\xfe\x00\x80")
    assert read_note("bin.dat") == ""
